<?php
require __DIR__ . '/../../api/config.php';
$publicLanding = ($_GET['public'] ?? '') === '1';
$user = $publicLanding ? current_user() : require_page_role('customer');
$customerMobile = '';
if (!$publicLanding && $user['role'] === 'customer') {
    $stmt = db()->prepare('SELECT mobile FROM users WHERE id = ?');
    $stmt->execute([$user['id']]);
    $mobile = $stmt->fetchColumn();
    $customerMobile = $mobile === false || $mobile === null ? '' : (string)$mobile;
}
header('Cache-Control: no-store');
?>
